SELECT *
FROM t_ddh_component_discovery_result
WHERE cluster_id = #{clusterId}
  AND service_name = #{serviceName}
ORDER BY discovery_start_time DESC

SELECT *
FROM t_ddh_component_discovery_result
WHERE cluster_id = #{clusterId}
  AND discovery_status = #{discoveryStatus}
ORDER BY discovery_start_time DESC

SELECT *
FROM t_ddh_component_discovery_result
WHERE cluster_id = #{clusterId}

    AND service_name = #{serviceName}

ORDER BY discovery_start_time DESC
LIMIT #{limit}

SELECT COUNT(*)
FROM t_ddh_component_discovery_result
WHERE cluster_id = #{clusterId}
  AND discovery_status = #{discoveryStatus}

SELECT *
FROM t_ddh_component_discovery_result
WHERE cluster_id = #{clusterId}
  AND discovery_start_time BETWEEN #{startTime} AND #{endTime}
ORDER BY discovery_start_time DESC
